  "Harekât kartlarını göster/gizle (P): dron kartı, PFD, telemetri karoları ve konsol 3B dünyanın üstünde yüzer; gizliyken sade görünüm (eski HUD ve alt çubuk komutları)": "Показать/скрыть карточки операций (P): карточка дрона, PFD, плитки телеметрии и консоль парят над 3D-миром; скрыты — простой вид (классический HUD и команды нижней панели)",
  "Harekât panelini aç/kapat (P)": "Показать/скрыть панель операций (P)",
