  "Farklı ışık ve açılarda ikinci bir tarama tanımayı daha güvenilir yapar. Gözlük takıyorsanız bu kez çıkarabilirsiniz.": "Второе сканирование при другом освещении и под другими углами делает распознавание надёжнее. Если вы носите очки, на этот раз их можно снять.",
  "Giriş ekranında şifre ya da PIN yerine yüzünüzle giriş yapın. Yüzünüz birkaç açıdan taranır; yalnızca matematiksel bir özet şifrelenerek saklanır, fotoğraf saklanmaz.": "Входите по лицу вместо пароля или PIN. Лицо сканируется с нескольких углов; сохраняется только зашифрованная математическая сводка, фото не хранится.",
