  "Güvenlik için mevcut şifreniz": "Ваш текущий пароль для безопасности", "Tamamla": "Завершить", "{n} / 9 açı": "{n} / 9 углов", "Yüzünüzü tanıtın": "Зарегистрируйте лицо",
