  "İkinci taramayı yap (önerilir)": "Выполнить второе сканирование (рекомендуется)", "Bitti": "Готово", "Hazır": "Готово",
  "Yüz ile giriş sistem yöneticisi tarafından kapatılmış.": "Вход по лицу отключён системным администратором.",
  "Yüz tanıma motoru bu sunucuda kurulu değil; yöneticinize başvurun.": "Модуль распознавания лиц не установлен на этом сервере; обратитесь к администратору.",
  "Bu cihazda bir kez şifreyle giriş yaptıktan sonra giriş ekranında adınıza dokunup yüzünüzle girebilirsiniz. Yüzünüzün yalnızca şifrelenmiş matematiksel özeti saklanır; fotoğraf saklanmaz.": "После одного входа по паролю на этом устройстве нажмите своё имя на экране входа и войдите по лицу. Хранится только зашифрованная математическая сводка лица, фото не сохраняется.",
  "Yüz tanıtılmamış": "Лицо не зарегистрировано", "Yüz tanıtıldı · {n} açı": "Лицо зарегистрировано · {n} углов", "Yalnız yüz": "Только лицо", "Yüz + PIN": "Лицо + PIN",
  "Önce PIN ile girişi açın": "Сначала включите вход по PIN", "Yüz doğrulandıktan sonra PIN de istenecek": "После подтверждения лица будет также запрошен PIN", "Yalnız yüz ile giriş": "Вход только по лицу",
  "Giriş kipi": "Режим входа", "Yüz doğrulanınca ek olarak PIN sorulur (daha güvenli)": "После подтверждения лица дополнительно запрашивается PIN (безопаснее)", "Yüz doğrulanınca doğrudan giriş": "Прямой вход после подтверждения лица",
  "Yeniden tanıt": "Зарегистрировать заново", "Yüz verisini sil": "Удалить данные лица",
  "Kayıtlı yüz özeti kalıcı olarak silinir; giriş ekranında yüz ile giriş kapanır. İstediğiniz zaman yeniden tanıtabilirsiniz.": "Сохранённая сводка лица удаляется безвозвратно; вход по лицу на экране входа отключается. Вы можете зарегистрировать лицо снова в любое время.",
  "Sil": "Удалить", "Yüz verisi silindi": "Данные лица удалены", "Kullanıcı bilgileri, şifre, PIN, yüz ile giriş": "Данные пользователя, пароль, PIN, вход по лицу", "Şifre kuralları, giriş, PIN ve yüz": "Правила пароля, вход, PIN и лицо",
  "Güvenilir cihazda kamerayla (Face ID tarzı) giriş. Yüz özeti sunucuda şifreli saklanır; kullanıcı Kişisel Ayarlar › Hesap’tan tanıtır.": "Вход по камере (в стиле Face ID) на доверенных устройствах. Сводка лица хранится на сервере в зашифрованном виде; пользователь регистрирует её в Личных настройках › Учётная запись.",
  "Yüz ile girişe izin ver": "Разрешить вход по лицу", "Kapatılırsa kimse yüzle giremez ve yeni yüz tanıtılamaz; mevcut kayıtlar silinmez": "Если отключено, никто не сможет войти по лицу или зарегистрировать новое; существующие записи сохраняются",
  "Eşleşme eşiği": "Порог совпадения", "Kosinüs benzerliği × 100. 45 önerilir; düşük = daha hoşgörülü (yanlış kabul riski), yüksek = daha sıkı (ışık değişiminde ret).": "Косинусное сходство × 100. Рекомендуется 45; ниже = мягче (риск ложного принятия), выше = строже (отказы при смене освещения).",
  "Canlılık adımı (baş çevirme)": "Проверка живости (поворот головы)", "Eşleşmeden sonra rastgele bir yöne hafifçe bakılması istenir; fotoğrafla kandırmayı zorlaştırır": "После совпадения просят слегка посмотреть в случайную сторону; затрудняет обман фотографией",
